public class Main {
    static class Student {
        String name;   // reference stored inside the heap object
        int marks;     // primitive stored inside the heap object
        Student(String name, int marks) { this.name = name; this.marks = marks; }
    }

    public static void main(String[] args) {
        int count = 1;                       // stack: primitive value
        String name = "Asha";                // stack: reference -> pooled String on heap
        Student s = new Student(name, 91);   // stack: reference -> Student on heap
        System.out.println(s.name + " " + s.marks + " " + count);
        s = null;                            // Student object now unreachable -> GC eligible
    }
}

