import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> lines = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) {
            if (!line.trim().isEmpty()) lines.add(line.trim());
        }
        String[] objects = lines.get(0).split("\\s+");
        Map<String, List<String>> refs = new HashMap<>();
        for (String o : objects) refs.put(o, new ArrayList<>());

        for (int i = 2; i < lines.size(); i++) {
            String[] p = lines.get(i).split("\\s+");
            if (refs.containsKey(p[0]) && refs.containsKey(p[1])) refs.get(p[0]).add(p[1]);
        }

        // Mark phase: iterative DFS from every root
        Set<String> marked = new HashSet<>();
        Deque<String> stack = new ArrayDeque<>();
        if (lines.size() > 1 && !lines.get(1).equals("-")) {
            for (String root : lines.get(1).split("\\s+")) {
                if (refs.containsKey(root) && marked.add(root)) stack.push(root);
            }
        }
        while (!stack.isEmpty()) {
            String current = stack.pop();
            for (String next : refs.get(current)) {
                if (marked.add(next)) stack.push(next);
            }
        }

        // Sweep phase: anything unmarked is garbage
        StringBuilder live = new StringBuilder();
        StringBuilder dead = new StringBuilder();
        for (String o : objects) {
            StringBuilder target = marked.contains(o) ? live : dead;
            if (target.length() > 0) target.append(' ');
            target.append(o);
        }
        System.out.println("Reachable: " + (live.length() == 0 ? "none" : live.toString()));
        System.out.println("Collected: " + (dead.length() == 0 ? "none" : dead.toString()));
    }
}

